GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Globally minimize maximum KVPR with a set-partitioning MILP over feasible subsets."""
    n = len(models)
    sizes = [m.model_size for m in models]
    loads = [m.req_rate / m.slo for m in models]

    if any(size >= GPU_MEM_SIZE for size in sizes):
        raise ValueError("A model leaves no KV cache memory on a GPU")

    def greedy():
        result = {g: [] for g in range(gpu_num)}
        memory = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for i in sorted(
            range(n),
            key=lambda i: loads[i] / (GPU_MEM_SIZE - sizes[i]),
            reverse=True,
        ):
            choices = [g for g in range(gpu_num) if memory[g] >= sizes[i]]
            if not choices:
                raise ValueError("Models cannot fit in the available GPU memory")
            g = min(choices, key=lambda g: (load[g] + loads[i]) / (memory[g] - sizes[i]))
            result[g].append(models[i])
            memory[g] -= sizes[i]
            load[g] += loads[i]
        return result

    # Full configuration enumeration is exact but intentionally bounded so that
    # unusually large instances retain the previous fast, feasible behavior.
    if n > 16:
        return greedy()

    configurations = []

    def enumerate_sets(start, chosen, used_memory, used_load):
        if chosen:
            configurations.append((
                tuple(chosen),
                used_load / (GPU_MEM_SIZE - used_memory),
            ))
        for i in range(start, n):
            new_memory = used_memory + sizes[i]
            if new_memory < GPU_MEM_SIZE:
                enumerate_sets(i + 1, chosen + [i], new_memory, used_load + loads[i])

    enumerate_sets(0, [], 0.0, 0.0)
    if not configurations:
        return greedy()

    try:
        import numpy as np
        from scipy.optimize import Bounds, LinearConstraint, milp
        from scipy.sparse import coo_matrix
    except ImportError:
        return greedy()

    count = len(configurations)
    # Variables are one binary selection value per subset plus epigraph t.
    # Every model is covered exactly once; at most gpu_num nonempty subsets
    # are selected, because any remaining GPUs are simply empty.
    rows, cols, data = [], [], []
    for j, (subset, pressure) in enumerate(configurations):
        for i in subset:
            rows.append(i)
            cols.append(j)
            data.append(1.0)
        rows.extend((n + 1, n + 2 + j))
        cols.extend((j, count))
        data.extend((1.0, -pressure))

    matrix = coo_matrix(
        (data, (rows, cols)),
        shape=(n + 2 + count, count + 1),
    ).tocsr()
    lower = np.r_[np.ones(n), -np.inf, np.full(count, -np.inf)]
    upper = np.r_[np.ones(n), float(gpu_num), np.zeros(count)]
    objective = np.r_[np.zeros(count), 1.0]

    try:
        answer = milp(
            c=objective,
            integrality=np.r_[np.ones(count), 0],
            bounds=Bounds(np.zeros(count + 1), np.full(count + 1, np.inf)),
            constraints=LinearConstraint(matrix, lower, upper),
        )
    except Exception:
        return greedy()

    if not answer.success or answer.x is None:
        return greedy()

    result = {g: [] for g in range(gpu_num)}
    selected = [j for j in range(count) if answer.x[j] > 0.5]
    if len(selected) > gpu_num:
        return greedy()
    for g, j in enumerate(selected):
        for i in configurations[j][0]:
            result[g].append(models[i])
    return result

